public interface ModemVisitor { }                        // degenerate base
public interface ZoomVisitor extends ModemVisitor { void visit(Zoom zoom); }

public final class Zoom extends Modem {
    @Override public void accept(ModemVisitor visitor) {
        if (visitor instanceof ZoomVisitor v) v.visit(this);
        else log.debug("visitor {} cannot visit Zoom", visitor);
    }
}
